                          <div style={styles.actionGroup}>
                            {!u.isVerified && <button style={styles.btnPurple} onClick={() => verifyUser(u._id, 'Provider')}>Verify</button>}
                            {u.isActive ? <button style={styles.btnDanger} onClick={() => updateUserStatus(u._id, false)}>Suspend</button> : <button style={styles.btnSuccess} onClick={() => updateUserStatus(u._id, true)}>Activate</button>}
                            <button style={styles.btnDanger} onClick={() => deleteUser(u._id, u.businessName || u.firstName)}>Delete</button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Drivers Tab */}
          {activeTab === 'drivers' && (
            <div style={styles.tableCard}>
              <div style={styles.tableHeader}><div style={styles.tableTitle}>Driver Management</div></div>
              <div style={styles.tableWrapper}>
                <table style={styles.table}>
                  <thead><tr><th style={styles.th}>Name</th><th style={styles.th}>Email</th><th style={styles.th}>Vehicle</th><th style={styles.th}>Stripe</th><th style={styles.th}>Status</th><th style={styles.th}>Online</th><th style={styles.th}>Actions</th></tr></thead>
                  <tbody>
                    {users.filter(u => u.role === 'driver').map(u => {
                      const isOnlineNow = onlineUsers.drivers.some(d => d.id === u._id || d.driverId === u._id);
                      return (
                        <tr key={u._id}>
                          <td style={styles.td}>{u.firstName} {u.lastName}</td>
                          <td style={styles.td}>{u.email}</td>
                          <td style={styles.td}>{u.vehicleModel || 'N/A'}</td>
                          <td style={styles.td}>{getStripeBadge(u.stripeAccountStatus)}</td>
                          <td style={styles.td}><span style={{ color: u.isVerified ? '#10b981' : '#f59e0b' }}>{u.isVerified ? 'Verified' : 'Pending'}</span></td>
                          <td style={styles.td}>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                              <span style={{ width: '8px', height: '8px', backgroundColor: isOnlineNow ? '#10b981' : '#6b7280', borderRadius: '50%', display: 'inline-block' }}></span>
                              {isOnlineNow ? 'Online' : 'Offline'}
                            </span>
                          </td>
                          <td style={styles.td}>
                            <div style={styles.actionGroup}>
                              {!u.isVerified && <button style={styles.btnPurple} onClick={() => verifyUser(u._id, 'Driver')}>Verify</button>}
                              {u.isActive ? <button style={styles.btnDanger} onClick={() => updateUserStatus(u._id, false)}>Suspend</button> : <button style={styles.btnSuccess} onClick={() => updateUserStatus(u._id, true)}>Activate</button>}
                              <button style={styles.btnDanger} onClick={() => deleteUser(u._id, `${u.firstName} ${u.lastName}`)}>Delete</button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Bookings Tab */}
          {activeTab === 'bookings' && (
            <div style={styles.tableCard}>
              <div style={styles.tableHeader}>
                <div style={styles.tableTitle}>All Bookings</div>
                <div style={styles.filters}>
                  <select style={styles.select} value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
                    <option value="all">All</option><option value="pending">Pending</option><option value="confirmed">Confirmed</option>
                    <option value="completed">Completed</option><option value="cancelled">Cancelled</option>
                  </select>
                  <input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} style={styles.searchInput} />
                </div>
              </div>
              <div style={styles.tableWrapper}>
                <table style={styles.table}>
                  <thead><tr><th style={styles.th}>Service</th><th style={styles.th}>Customer</th><th style={styles.th}>Provider</th><th style={styles.th}>Date</th><th style={styles.th}>Amount</th><th style={styles.th}>Status</th></tr></thead>
                  <tbody>
                    {filteredBookings.map(b => (
                      <tr key={b._id}>
                        <td style={styles.td}>{b.serviceName}</td>
                        <td style={styles.td}>{b.customerId?.firstName} {b.customerId?.lastName}</td>
                        <td style={styles.td}>{b.providerId?.businessName || b.providerId?.firstName}</td>
                        <td style={styles.td}>{new Date(b.bookingDate).toLocaleDateString()}</td>
                        <td style={styles.td}>${b.totalAmount}</td>
                        <td style={styles.td}>{getStatusBadge(b.status)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Services Tab */}
          {activeTab === 'services' && (
            <div style={styles.tableCard}>
              <div style={styles.tableHeader}><div style={styles.tableTitle}>All Services</div></div>
              <div style={styles.tableWrapper}>
                <table style={styles.table}>
                  <thead><tr><th style={styles.th}>Name</th><th style={styles.th}>Provider</th><th style={styles.th}>Price</th><th style={styles.th}>Status</th><th style={styles.th}>Actions</th></tr></thead>
                  <tbody>
                    {services.map(s => (
                      <tr key={s._id}>
                        <td style={styles.td}>{s.name}</td>
                        <td style={styles.td}>{s.providerId?.businessName || s.providerId?.firstName}</td>
                        <td style={styles.td}>${s.price}</td>
                        <td style={styles.td}><span style={{ color: s.isActive ? '#10b981' : '#ef4444' }}>{s.isActive ? 'Active' : 'Hidden'}</span></td>
                        <td style={styles.td}><button style={s.isActive ? styles.btnDanger : styles.btnSuccess} onClick={() => toggleServiceStatus(s._id, s.isActive)}>{s.isActive ? 'Hide' : 'Show'}</button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Revenue Tab */}
          {activeTab === 'revenue' && (
            <div>
              <div style={styles.revenueGrid}>
                <div style={styles.revenueCard}><div>Total Revenue</div><div style={styles.revenueValue}>${stats.payments?.totalRevenue?.toLocaleString() || 0}</div></div>
                <div style={styles.revenueCard}><div>Platform Commission</div><div style={styles.revenueValue}>${stats.payments?.totalCommission?.toLocaleString() || 0}</div></div>
                <div style={styles.revenueCard}><div>Provider Payouts</div><div style={styles.revenueValue}>${stats.payments?.totalProviderPayouts?.toLocaleString() || 0}</div></div>
                <div style={styles.revenueCard}><div>Driver Payouts</div><div style={styles.revenueValue}>${stats.payments?.totalDriverPayouts?.toLocaleString() || 0}</div></div>
              </div>
              <div style={styles.tableCard}>
                <div style={styles.tableHeader}><div style={styles.tableTitle}>Monthly Revenue Breakdown</div></div>
                <div style={styles.chartContainer}>
                  {paymentAnalytics.monthlyRevenue?.map(m => (
                    <div key={m.month} style={styles.chartBar}>
                      <div style={{ ...styles.barFill, height: `${(m.revenue / maxRevenue) * 150}px`, backgroundColor: '#8b5cf6' }}></div>
                      <div style={{ ...styles.barFillSmall, height: `${(m.commission / maxRevenue) * 150}px`, backgroundColor: '#f59e0b' }}></div>
                      <span style={{ fontSize: '11px', color: darkMode ? 'white' : '#374151' }}>{m.month}</span>
                    </div>
                  ))}
                </div>
              </div>
              <div style={styles.tableCard}>
                <div style={styles.tableHeader}><div style={styles.tableTitle}>Recent Transactions</div></div>
                <div style={styles.tableWrapper}>
                  {paymentAnalytics.recentTransactions?.map(t => (
                    <div key={t._id} style={styles.transactionItem}>
                      <div><strong>{t.bookingId?.serviceName}</strong><div style={{ fontSize: '11px', color: '#6b7280' }}>{t.customerId?.firstName} {t.customerId?.lastName}</div></div>
                      <div>${t.amount}</div>
                      <div>{t.paymentMethod}</div>
                      <div>{new Date(t.paidAt).toLocaleDateString()}</div>
                      <button onClick={() => downloadInvoice(t._id)} style={styles.invoiceBtn}>Invoice</button>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Payouts Tab */}
          {activeTab === 'payouts' && (
            <div>
              <div style={styles.tableCard}>
                <div style={styles.tableHeader}><div style={styles.tableTitle}>Provider Payouts</div></div>
                {pendingPayouts.providerPayouts?.map(p => (
                  <div key={p.id} style={styles.pendingItem}>
                    <span><strong>{p.name}</strong> - {p.count} bookings</span>
                    <span style={{ fontWeight: 'bold', color: '#10b981' }}>${p.amount?.toLocaleString() || 0}</span>
                    <button style={styles.btnSuccess} onClick={() => processPayout(p.id, 'provider')}>Process Payment</button>
                  </div>
                ))}
                {pendingPayouts.providerPayouts?.length === 0 && <div style={styles.emptyState}>No pending provider payouts</div>}
              </div>
              <div style={styles.tableCard}>
                <div style={styles.tableHeader}><div style={styles.tableTitle}>Driver Payouts</div></div>
                {pendingPayouts.driverPayouts?.map(d => (
                  <div key={d.id} style={styles.pendingItem}>
                    <span><strong>{d.name}</strong> - {d.count} deliveries</span>
                    <span style={{ fontWeight: 'bold', color: '#10b981' }}>${d.amount?.toLocaleString() || 0}</span>
                    <button style={styles.btnSuccess} onClick={() => processPayout(d.id, 'driver')}>Process Payment</button>
                  </div>
                ))}
                {pendingPayouts.driverPayouts?.length === 0 && <div style={styles.emptyState}>No pending driver payouts</div>}
              </div>
            </div>
          )}

          {/* Refunds Tab */}
          {activeTab === 'refunds' && (
            <div style={styles.tableCard}>
              <div style={styles.tableHeader}>
                <div style={styles.tableTitle}>Refund Requests {pendingRefunds > 0 && <span style={{ backgroundColor: '#ef4444', color: 'white', padding: '2px 8px', borderRadius: '20px', fontSize: '11px', marginLeft: '8px' }}>{pendingRefunds} pending</span>}</div>
              </div>
              <div style={styles.tableWrapper}>
                <table style={styles.table}>
                  <thead><tr><th style={styles.th}>Customer</th><th style={styles.th}>Service</th><th style={styles.th}>Amount</th><th style={styles.th}>Reason</th><th style={styles.th}>Status</th><th style={styles.th}>Requested</th><th style={styles.th}>Actions</th></tr></thead>
                  <tbody>
                    {refunds.map(r => (
                      <tr key={r._id}>
                        <td style={styles.td}><strong>{r.customerId?.firstName} {r.customerId?.lastName}</strong><br/><span style={{ fontSize: '11px', color: '#6b7280' }}>{r.customerId?.email}</span></td>
                        <td style={styles.td}>{r.bookingId?.serviceName}</td>
                        <td style={styles.td}>${r.amount}</td>
                        <td style={styles.td}>{r.reason?.substring(0, 50)}...</td>
                        <td style={styles.td}>{getRefundStatusBadge(r.status)}</td>
                        <td style={styles.td}>{new Date(r.requestedAt).toLocaleDateString()}</td>
                        <td style={styles.td}>{r.status === 'pending' && <button style={styles.btnPurple} onClick={() => setSelectedRefund(r)}>Review</button>}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* NEW: Reviews Tab */}
          {activeTab === 'reviews' && (
            <div style={styles.tableCard}>
              <div style={styles.tableHeader}>
                <div style={styles.tableTitle}>Customer Reviews</div>
                <button style={styles.btnPrimary} onClick={fetchAllReviews}>Refresh</button>
              </div>
              <div style={styles.tableWrapper}>
                {reviewsLoading ? (
                  <div style={styles.emptyState}>Loading reviews...</div>
                ) : allReviews.length === 0 ? (
                  <div style={styles.emptyState}>No reviews yet.</div>
                ) : (
                  <table style={styles.table}>
                    <thead>
                      <tr>
                        <th style={styles.th}>Customer</th>
                        <th style={styles.th}>Provider</th>
                        <th style={styles.th}>Rating</th>
                        <th style={styles.th}>Review</th>
                        <th style={styles.th}>Date</th>
                        <th style={styles.th}>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {allReviews.map(review => (
                        <tr key={review._id}>
                          <td style={styles.td}>{review.customerId?.firstName} {review.customerId?.lastName}</td>
                          <td style={styles.td}>{review.providerId?.businessName || review.providerId?.firstName}</td>
                          <td style={styles.td}>{review.providerRating}/5</td>
                          <td style={styles.td}>{review.providerReview?.substring(0, 80)}...</td>
                          <td style={styles.td}>{new Date(review.createdAt).toLocaleDateString()}</td>
                          <td style={styles.td}>
                            <button onClick={() => hideReview(review._id)} style={styles.btnDanger}>Hide</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          )}

          {/* NEW: Promo Codes Tab */}
          {activeTab === 'promos' && (
            <div style={styles.tableCard}>
              <div style={styles.tableHeader}>
                <div style={styles.tableTitle}>Promo Codes</div>
                <button style={styles.btnSuccess} onClick={() => { setNewPromoCode({ code: '', description: '', discountType: 'percentage', discountValue: '', minPurchase: '', usageLimit: '', validUntil: '' }); setShowPromoModal(true); }}>+ Create Promo Code</button>
              </div>
              <div style={styles.tableWrapper}>
                {promoCodes.length === 0 ? (
                  <div style={styles.emptyState}>No promo codes created yet.</div>
                ) : (
                  <table style={styles.table}>
                    <thead>
                      <tr>
                        <th style={styles.th}>Code</th><th style={styles.th}>Description</th><th style={styles.th}>Discount</th>
                        <th style={styles.th}>Used/Limit</th><th style={styles.th}>Valid Until</th><th style={styles.th}>Status</th><th style={styles.th}>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {promoCodes.map(promo => (
                        <tr key={promo._id}>
                          <td style={styles.td}><strong>{promo.code}</strong></td>
                          <td style={styles.td}>{promo.description}</td>
                          <td style={styles.td}>{promo.discountType === 'percentage' ? `${promo.discountValue}%` : `$${promo.discountValue}`}</td>
                          <td style={styles.td}>{promo.usedCount} / {promo.usageLimit}</td>
                          <td style={styles.td}>{promo.validUntil ? new Date(promo.validUntil).toLocaleDateString() : 'Never'}</td>
                          <td style={styles.td}><span style={{ color: promo.isActive ? '#10b981' : '#ef4444' }}>{promo.isActive ? 'Active' : 'Inactive'}</span></td>
                          <td style={styles.td}><button onClick={() => deletePromoCode(promo._id, promo.code)} style={styles.btnDanger}>Delete</button></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          )}

          {/* NEW: Loyalty Tab */}
          {activeTab === 'loyalty' && (
            <div>
              <div style={styles.revenueGrid}>
                <div style={styles.revenueCard}><div style={{ fontSize: '24px' }}>💎</div><div>Total Points Issued</div><div style={styles.revenueValue}>{loyaltyStats.totalPoints.toLocaleString()}</div></div>
                <div style={styles.revenueCard}><div style={{ fontSize: '24px' }}>👥</div><div>Active Loyalty Users</div><div style={styles.revenueValue}>{loyaltyStats.totalUsers}</div></div>
                <div style={styles.revenueCard}><div style={{ fontSize: '24px' }}>📊</div><div>Average Points per User</div><div style={styles.revenueValue}>{loyaltyStats.averagePoints.toLocaleString()}</div></div>
              </div>
              <div style={styles.tableCard}>
                <div style={styles.tableHeader}><div style={styles.tableTitle}>Loyalty Leaderboard</div></div>
                <div style={styles.tableWrapper}>
                  {loyaltyLeaderboard.length === 0 ? (
                    <div style={styles.emptyState}>No loyalty data yet.</div>
                  ) : (
                    <table style={styles.table}>
                      <thead>
                        <tr>
                          <th style={styles.th}>Rank</th><th style={styles.th}>User</th><th style={styles.th}>Tier</th>
                          <th style={styles.th}>Points</th><th style={styles.th}>Lifetime Points</th>
                        </tr>
                      </thead>
                      <tbody>
                        {loyaltyLeaderboard.map((user, index) => (
                          <tr key={user.userId?._id || index}>
                            <td style={styles.td}>{index === 0 ? '🥇' : index === 1 ? '🥈' : index === 2 ? '🥉' : `${index + 1}`}</td>
                            <td style={styles.td}>{user.userId?.firstName} {user.userId?.lastName}{user.userId?.businessName && <div style={{ fontSize: '11px', color: '#6b7280' }}>{user.userId.businessName}</div>}</td>
                            <td style={styles.td}><span style={{ backgroundColor: user.tier === 'Platinum' ? '#e0e7ff' : user.tier === 'Gold' ? '#fef3c7' : '#f3e8ff', color: user.tier === 'Platinum' ? '#4338ca' : user.tier === 'Gold' ? '#92400e' : '#7c3aed', padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>{user.tier || 'Bronze'}</span></td>
                            <td style={styles.td}>{user.points?.toLocaleString() || 0}</td>
                            <td style={styles.td}>{user.lifetimePoints?.toLocaleString() || 0}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Refund Review Modal */}
      {selectedRefund && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2 style={{ marginBottom: '20px' }}>Review Refund Request</h2>
            <div style={{ marginBottom: '20px' }}>
              <p><strong>Customer:</strong> {selectedRefund.customerId?.firstName} {selectedRefund.customerId?.lastName}</p>
              <p><strong>Email:</strong> {selectedRefund.customerId?.email}</p>
              <p><strong>Service:</strong> {selectedRefund.bookingId?.serviceName}</p>
              <p><strong>Amount:</strong> ${selectedRefund.amount}</p>
              <p><strong>Reason:</strong> {selectedRefund.reason}</p>
            </div>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '500' }}>Admin Notes (Optional)</label>
            <textarea style={styles.modalTextarea} placeholder="Add internal notes..." value={adminNotes} onChange={(e) => setAdminNotes(e.target.value)} rows="3" />
            <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
              <button style={{ backgroundColor: '#10b981', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => approveRefund(selectedRefund._id)}>Approve Refund</button>
              <button style={{ backgroundColor: '#ef4444', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => { setRejectionReason(''); }}>Reject</button>
              <button style={{ backgroundColor: '#6b7280', color: 'white', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => { setSelectedRefund(null); setAdminNotes(''); setRejectionReason(''); }}>Cancel</button>
            </div>
            {rejectionReason && (
              <div style={{ marginTop: '20px', paddingTop: '20px', borderTop: '1px solid #e5e7eb' }}>
                <label style={{ display: 'block', marginBottom: '8px', fontWeight: '500' }}>Rejection Reason *</label>
                <textarea style={styles.modalTextarea} placeholder="Why is this refund being rejected?" value={rejectionReason} onChange={(e) => setRejectionReason(e.target.value)} rows="2" />
                <button style={{ marginTop: '10px', backgroundColor: '#ef4444', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer' }} onClick={() => rejectRefund(selectedRefund._id)}>Confirm Rejection</button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Promo Code Create Modal */}
      {showPromoModal && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2 style={{ marginBottom: '20px' }}>Create Promo Code</h2>
            <form onSubmit={createPromoCode}>
              <input style={styles.input} type="text" placeholder="Code (e.g., WELCOME20)" value={newPromoCode.code} onChange={(e) => setNewPromoCode({...newPromoCode, code: e.target.value.toUpperCase()})} required />
              <input style={styles.input} type="text" placeholder="Description" value={newPromoCode.description} onChange={(e) => setNewPromoCode({...newPromoCode, description: e.target.value})} required />
              <select style={styles.input} value={newPromoCode.discountType} onChange={(e) => setNewPromoCode({...newPromoCode, discountType: e.target.value})}>
                <option value="percentage">Percentage (%)</option>
                <option value="fixed">Fixed Amount ($)</option>
              </select>
              <input style={styles.input} type="number" placeholder="Discount Value" value={newPromoCode.discountValue} onChange={(e) => setNewPromoCode({...newPromoCode, discountValue: e.target.value})} required />
              <input style={styles.input} type="number" placeholder="Minimum Purchase (optional)" value={newPromoCode.minPurchase} onChange={(e) => setNewPromoCode({...newPromoCode, minPurchase: e.target.value})} />
              <input style={styles.input} type="number" placeholder="Usage Limit" value={newPromoCode.usageLimit} onChange={(e) => setNewPromoCode({...newPromoCode, usageLimit: e.target.value})} />
              <input style={styles.input} type="date" placeholder="Valid Until" value={newPromoCode.validUntil} onChange={(e) => setNewPromoCode({...newPromoCode, validUntil: e.target.value})} />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Create</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowPromoModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminDashboard;
